CREATE TABLE IF NOT EXISTS visits (sid TEXT PRIMARY KEY, source TEXT NOT NULL, ua TEXT NOT NULL, model TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS entries (sid TEXT PRIMARY KEY REFERENCES visits(sid), nickname TEXT NOT NULL, team TEXT NOT NULL, size TEXT NOT NULL, claim TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS winner (id INTEGER PRIMARY KEY CHECK(id=1), claim TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shipping (sid TEXT PRIMARY KEY REFERENCES entries(sid), recipient TEXT NOT NULL, address TEXT NOT NULL, city TEXT NOT NULL, region TEXT NOT NULL, postcode TEXT NOT NULL, country TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
